import csv


def parse_record(line: str) -> dict[str, str]:
    rows = list(csv.reader([line]))
    if len(rows) != 1 or len(rows[0]) != 2:
        raise ValueError("expected exactly two CSV fields")
    name, email = rows[0]
    return {"name": name, "email": email}

